-- the reviewed T13 body + the anonymous refusal (S2-1)
create or replace function private.account_lifecycle_assert_active_service_write(p_user_id uuid, p_service_key text)
returns void language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_legacy_sub text := nullif(current_setting('request.jwt.claim.sub', true), '');
  v_claims jsonb;
  v_sub text;
  v_role text;
  v_session text;
  v_anonymous text;
  v_subject uuid;
  v_session_id uuid;
  v_account public.common_accounts;
  v_status text;
  v_live boolean;
begin
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'ACCOUNT_LIFECYCLE_WRITER_FENCE_UNAVAILABLE' using errcode = '42501';
  end if;
  if p_service_key is null or p_service_key not in ('kabumori', 'x_autopost') then
    raise exception 'ACCOUNT_LIFECYCLE_SERVICE_INVALID' using errcode = '42501';
  end if;

  -- 1. The person, from the one claim source auth.uid() reads first: the per-claim settings of an
  --    older PostgREST when present, else the JSON claims. Never p_user_id alone.
  if v_legacy_sub is not null then
    v_sub := v_legacy_sub;
    v_role := nullif(current_setting('request.jwt.claim.role', true), '');
    v_session := nullif(current_setting('request.jwt.claim.session_id', true), '');
    v_anonymous := nullif(current_setting('request.jwt.claim.is_anonymous', true), '');
  else
    begin
      v_claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
    exception when others then
      v_claims := null;
    end;
    if jsonb_typeof(v_claims) = 'object' then
      v_sub := v_claims ->> 'sub';
      v_role := v_claims ->> 'role';
      v_session := v_claims ->> 'session_id';
      v_anonymous := case when jsonb_typeof(v_claims -> 'is_anonymous') = 'boolean' then v_claims ->> 'is_anonymous' end;
    end if;
  end if;
  begin
    v_subject := v_sub::uuid;
    v_session_id := v_session::uuid;
  exception when others then
    raise exception 'ACCOUNT_LIFECYCLE_AUTH_REQUIRED' using errcode = '42501';
  end;
  -- (S2-1, G5-24 / G5-25) an anonymous sign-in is not a person: refused here, before any lock. Only a PROVEN non-anonymous caller
  -- passes: the JSON claim must be the boolean false, the per-claim setting exactly 'false'; missing, null, empty, another type or
  -- any other value is refused (H4 P2 on PR #480).
  if p_user_id is null or v_subject is null or v_session_id is null or v_role is distinct from 'authenticated'
     or v_anonymous is distinct from 'false'
     or v_subject <> p_user_id or (select auth.uid()) is distinct from p_user_id then
    raise exception 'ACCOUNT_LIFECYCLE_AUTH_REQUIRED' using errcode = '42501';
  end if;

  -- 2. I1 lock order: login KEY SHARE -> account FOR UPDATE (the lifecycle lock), then the entitlement.
  --    Nothing is created. Every read below is a fresh READ COMMITTED snapshot taken after the waits.
  v_account := private.account_lifecycle_lock(p_user_id, false);
  if v_account.user_id is null then
    raise exception 'ACCOUNT_LIFECYCLE_ACCOUNT_NOT_FOUND' using errcode = '42501';
  end if;
  if v_account.status = 'deleting'
     or exists (select 1 from private.account_lifecycle_operations o
                 where o.user_id = p_user_id and o.operation_type = 'account_deletion' and o.status = 'in_progress') then
    raise exception 'ACCOUNT_DELETION_IN_PROGRESS' using errcode = '42501';
  end if;
  if v_account.status <> 'active' then
    raise exception 'ACCOUNT_LOCKED' using errcode = '42501';
  end if;
  select e.status into v_status from public.service_entitlements e
   where e.user_id = p_user_id and e.service_key = p_service_key
   for update;
  if not found then
    raise exception 'SERVICE_NOT_REGISTERED' using errcode = '42501';
  end if;
  if v_status = 'deleting'
     or exists (select 1 from private.account_lifecycle_operations o
                 where o.user_id = p_user_id and o.operation_type = 'service_deletion'
                   and o.service_key = p_service_key and o.status = 'in_progress') then
    raise exception 'SERVICE_DELETION_IN_PROGRESS' using errcode = '42501';
  end if;
  if v_status <> 'active' then
    raise exception 'SERVICE_NOT_ACTIVE' using errcode = '42501';
  end if;

  -- 3. The session is still live, read after the locks: a logout or revocation that committed while
  --    this waited is seen. Read only; GoTrue owns these rows and nothing here locks them.
  begin
    v_live := exists (select 1 from auth.sessions s
                       where s.id = v_session_id and s.user_id = p_user_id
                         and (s.not_after is null or s.not_after > clock_timestamp()));
  exception when undefined_table or undefined_column or insufficient_privilege then
    raise exception 'ACCOUNT_LIFECYCLE_WRITER_FENCE_UNAVAILABLE' using errcode = '42501';
  end;
  if not v_live then
    raise exception 'ACCOUNT_LIFECYCLE_AUTH_REQUIRED' using errcode = '42501';
  end if;
end;
$$;

do $$
declare
  v_owner oid := (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user);
  v_fn regprocedure := pg_catalog.to_regprocedure('private.account_lifecycle_assert_active_service_write(uuid,text)');
begin
  -- the same function (same OID: every consumer's reference and its ACL are kept), now with exactly the expected body
  if v_fn is null or v_fn::oid::text is distinct from pg_catalog.current_setting('postona_personal_s2_1.oid', true) then
    raise exception 'T13_ANON_POSTCONDITION_OID';
  end if;
  if (select pg_catalog.md5(p.prosrc) from pg_catalog.pg_proc p where p.oid = v_fn) is distinct from '1f8cd9c764c251f3232c61b7a77ff597' then
    raise exception 'T13_ANON_POSTCONDITION_BODY';
  end if;
  -- the function is the reviewed T13 in every other respect: owner, definer, volatile, empty search_path, plpgsql, returns void, the
  -- attributes below, EXECUTE for its owner alone, and no API role reaches it through any membership (direct or indirect, INHERIT or not).
  -- (G5-30) `is not true`: a NULL (a RESET ALL leaves proconfig NULL) refuses, it no longer slips through `not (...)`
  if (select p.proowner from pg_catalog.pg_proc p where p.oid = v_fn) is distinct from v_owner
     or (select p.prosecdef and p.provolatile = 'v' and p.prorettype = 'void'::pg_catalog.regtype
                and p.prolang = (select l.oid from pg_catalog.pg_language l where l.lanname = 'plpgsql')
                and p.proconfig = array['search_path=""']
                -- (G5-30) every attribute a CREATE OR REPLACE resets without an error, at the value measured on the reviewed T13: not STRICT,
                -- not LEAKPROOF, PARALLEL UNSAFE, COST 100, no support function, no TRANSFORM, ROWS 0, no argument modes
                and not p.proisstrict and not p.proleakproof and p.proparallel = 'u' and p.procost = 100
                and p.prosupport::oid = 0 and p.protrftypes is null and p.prorows = 0 and p.proargmodes is null
           from pg_catalog.pg_proc p where p.oid = v_fn) is not true
     or (select pg_catalog.array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_fn)
          is distinct from pg_catalog.format('%s=X/%s', pg_catalog.quote_ident(current_user), pg_catalog.quote_ident(current_user))
     or exists (select 1 from pg_catalog.pg_roles r
                 where r.rolname in ('anon', 'authenticated', 'service_role', 'authenticator')
                   and (pg_catalog.has_function_privilege(r.oid, v_fn, 'EXECUTE') or pg_catalog.pg_has_role(r.oid, v_owner, 'MEMBER'))) then
    raise exception 'T13_ANON_POSTCONDITION_SHAPE';
  end if;
end $$;


-- ==== from part 50_s2_3_workspace_eligibility.sql: the S2-3 PREDICATE only -- its relation / derivation preconditions (lines 64-95)
-- inside this wrapper, then lines 98-143 (create + revoke), verbatim. Part 50's R0 checks and R0 body are not part of the MVP. ====
do $$
declare
  v_owner oid := (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user);
  v_rel text;
  v_kind "char";
  v_rls boolean;
  v_forced boolean;
  v_relowner oid;
begin
  -- the predicate is new: a function already under its name is someone else's
  if pg_catalog.to_regprocedure('private.postona_personal_workspace_eligibility(uuid)') is not null then
    raise exception 'S23_PRECONDITION_PREDICATE_EXISTS';
  end if;
  -- the relations the predicate reads: plain tables this owner may SELECT, with EVERY row visible to it (the G5-08 rule: RLS off, BYPASSRLS, or the
  -- table owner's privileges with RLS not FORCED) -- a hidden membership would turn a conflict into 'absent' / 'own'; and the expected columns
  foreach v_rel in array array['public.brands', 'public.brand_memberships'] loop
    select c.relkind, c.relrowsecurity, c.relforcerowsecurity, c.relowner into v_kind, v_rls, v_forced, v_relowner
      from pg_catalog.pg_class c where c.oid = pg_catalog.to_regclass(v_rel);
    if not found or v_kind not in ('r', 'p') or not pg_catalog.has_table_privilege(v_owner, v_rel, 'SELECT') then
      raise exception 'S23_PRECONDITION_RELATION %', v_rel;
    end if;
    if v_forced then
      raise exception 'S23_PRECONDITION_RLS_FORCED %', v_rel;
    end if;
    if v_rls and not (select r.rolbypassrls from pg_catalog.pg_roles r where r.oid = v_owner) and not pg_catalog.pg_has_role(v_owner, v_relowner, 'USAGE') then
      raise exception 'S23_PRECONDITION_RLS_HIDES_ROWS %', v_rel;
    end if;
  end loop;
  if (select pg_catalog.count(*) from pg_catalog.pg_attribute a where a.attrelid = 'public.brands'::pg_catalog.regclass and not a.attisdropped
       and ((a.attname = 'id' and a.atttypid = 'text'::pg_catalog.regtype) or (a.attname = 'code_profile_key' and a.atttypid = 'text'::pg_catalog.regtype))) <> 2
     or (select pg_catalog.count(*) from pg_catalog.pg_attribute a where a.attrelid = 'public.brand_memberships'::pg_catalog.regclass and not a.attisdropped
       and ((a.attname = 'brand_id' and a.atttypid = 'text'::pg_catalog.regtype) or (a.attname = 'user_id' and a.atttypid = 'uuid'::pg_catalog.regtype)
         or (a.attname = 'role' and a.atttypid = 'text'::pg_catalog.regtype))) <> 3 then
    raise exception 'S23_PRECONDITION_RELATION_SHAPE';
  end if;
  -- the derivation must be the one the deletion saga names (main 20260928160000:98-100), as R0's own install checks
  if pg_catalog.to_regprocedure('public.social_mobile_account_deletion_workspace(uuid)') is null
     or public.social_mobile_account_deletion_workspace('00000000-0000-4000-8000-000000000001'::uuid)
        is distinct from 'u_' || pg_catalog.substr(pg_catalog.md5('00000000-0000-4000-8000-000000000001'), 1, 24) then
    raise exception 'S23_PRECONDITION_WORKSPACE_DERIVATION';
  end if;
end $$;

-- S2-3: the personal-workspace eligibility (owner-only)
create function private.postona_personal_workspace_eligibility(p_user uuid)
returns text language plpgsql stable security definer set search_path = '' set row_security = off as $$
declare
  v_workspace text;
  f_ws_found boolean;
  f_ws_kind text;
  f_caller_role text;
  f_owner uuid;
  f_owner_count bigint;
  f_member_count bigint;
  f_orphans bigint;
  f_other_owned boolean;
begin
  if p_user is null then
    raise exception 'POSTONA_PERSONAL_WORKSPACE_USER_REQUIRED' using errcode = '22004';
  end if;
  -- the derived id, as the begin RPC, the deletion saga and R0 name it ('u_' || substr(md5(user), 1, 24))
  v_workspace := 'u_' || pg_catalog.substr(pg_catalog.md5(p_user::text), 1, 24);
  -- every fact in ONE statement (STABLE: the caller's snapshot), read as the lifecycle owner with every row visible (install check)
  select b.id is not null, b.code_profile_key,
         (select m.role from public.brand_memberships m where m.brand_id = b.id and m.user_id = p_user),
         (select case when pg_catalog.count(*) = 1 then (pg_catalog.array_agg(m.user_id))[1] end
            from public.brand_memberships m where m.brand_id = b.id and m.role = 'owner'),
         (select pg_catalog.count(*) from public.brand_memberships o where o.brand_id = b.id and o.role = 'owner'),
         (select pg_catalog.count(*) from public.brand_memberships o where o.brand_id = b.id),
         (select pg_catalog.count(*) from public.brand_memberships o where o.brand_id = v_workspace),
         exists (select 1 from public.brand_memberships o where o.user_id = p_user and o.role = 'owner' and o.brand_id <> v_workspace)
    into f_ws_found, f_ws_kind, f_caller_role, f_owner, f_owner_count, f_member_count, f_orphans, f_other_owned
    from (select 1) x
    left join public.brands b on b.id = v_workspace;
  -- the G5-23 section 4.1 rule (= PR #124's provisioner): the id above, kind social_mobile_user_v1, exactly one membership (the caller as owner),
  -- and the person owns NO other brand. The first four branches keep R0's reviewed answers; the last three are the S2-3 additions.
  return case
    when not f_ws_found and f_orphans = 0 and not f_other_owned then 'absent'
    when not f_ws_found then 'OWN_WORKSPACE_CONFLICT'  -- memberships under the id without its brand row, or another owned brand
    when f_ws_kind is distinct from 'social_mobile_user_v1' then 'OWN_WORKSPACE_CONFLICT'
    when f_owner_count <> 1 or f_owner is null then 'WORKSPACE_OWNER_UNKNOWN'
    when f_owner <> p_user or f_caller_role is distinct from 'owner' then 'OWN_WORKSPACE_CONFLICT'
    when f_member_count <> 1 then 'OWN_WORKSPACE_CONFLICT'  -- (S2-3) another member on the own workspace: it is not personal
    when f_other_owned then 'OWN_WORKSPACE_CONFLICT'        -- (S2-3) the person owns another brand (legacy / shared: PENDING P-1)
    else 'own'
  end;
end $$;

revoke all on function private.postona_personal_workspace_eligibility(uuid) from public, anon, authenticated, service_role;

-- ==== from part 10_r1_authorization_verdict.sql: the generation coverage GC only (lines 98-130), verbatim. R1 / W1 / W2 are not part of
-- the MVP (they read the owner epoch). ====
-- The service generation W1 compares is the owner's lifecycle_version, moved only by F5 P1's two triggers. They count only when they are EXACTLY
-- the P1 triggers (H1 C1 P2 on PR #358): the entitlement trigger AFTER INSERT OR UPDATE OR DELETE FOR EACH ROW (tgtype 29), the account trigger
-- BEFORE UPDATE FOR EACH ROW (tgtype 19), each enabled, not internal, no WHEN clause, no column list, not a constraint / deferrable trigger, no
-- arguments, no transition tables, bound to its P1 function (owned by the table owner, definer, empty search path); no OTHER BEFORE ROW UPDATE
-- trigger on public.common_accounts (one firing after it could put lifecycle_version back), no rule on either table (a DO INSTEAD rule would swallow
-- the bump), and this session honours triggers. Used by the install (pre and post) and by W1 on every call.
create function private.account_lifecycle_generation_covered()
returns boolean language sql stable security definer set search_path = '' set row_security = off as $$
  select pg_catalog.current_setting('session_replication_role') = 'origin'
     and (select pg_catalog.count(*) from pg_catalog.pg_trigger t join pg_catalog.pg_proc f on f.oid = t.tgfoid
           where not t.tgisinternal and t.tgenabled in ('O', 'A')
             and t.tgqual is null and pg_catalog.cardinality(t.tgattr::int2[]) = 0 and t.tgconstraint = 0 and not t.tgdeferrable and not t.tginitdeferred
             and t.tgnargs = 0 and t.tgoldtable is null and t.tgnewtable is null
             and f.proowner = (select c.relowner from pg_catalog.pg_class c where c.oid = t.tgrelid)
             and f.prosecdef and f.proconfig @> array['search_path=""']
             and ((t.tgrelid = 'public.service_entitlements'::regclass and t.tgname = 'account_lifecycle_touch_entitlement' and t.tgtype = 29
                   and t.tgfoid = 'private.account_lifecycle_touch_entitlement()'::regprocedure)
               or (t.tgrelid = 'public.common_accounts'::regclass and t.tgname = 'account_lifecycle_touch_account' and t.tgtype = 19
                   and t.tgfoid = 'private.account_lifecycle_touch_account()'::regprocedure))) = 2
     and not exists (select 1 from pg_catalog.pg_trigger t
                      where t.tgrelid = 'public.common_accounts'::regclass and not t.tgisinternal and t.tgenabled <> 'D'
                        and t.tgtype & 1 = 1 and t.tgtype & 2 = 2 and t.tgtype & 16 = 16
                        and t.tgname <> 'account_lifecycle_touch_account')
     and not exists (select 1 from pg_catalog.pg_rewrite r where r.ev_class in ('public.common_accounts'::regclass, 'public.service_entitlements'::regclass))
$$;
revoke all on function private.account_lifecycle_generation_covered() from public, anon, authenticated, service_role;

do $$
begin
  if not private.account_lifecycle_generation_covered() then
    raise exception 'AUTH_VERDICT_PRECONDITION_LIFECYCLE_TRIGGERS';
  end if;
end $$;

-- ==== parts/M10_personal_worker_verdict.sql: its own begin; / commit; removed, nothing else changed ====
-- G5 SOURCE CANDIDATE (2026-10-28, Issue #320 G5-01 task 46). NOT in supabase/migrations/, NOT applied anywhere. Part of the PERSONAL MVP
-- profile (../MVP_INSTALL.sql); installable alone for tests. Production NO_GO without one independent review of this profile, the G5 担当ちゃ's
-- acceptance and the owner's explicit production approval.
--
-- MV  private.postona_personal_worker_verdict(uuid, text, text, bigint) -> text            EXECUTE: the lifecycle owner ONLY (no grant)
--     The personal-MVP fence for a job that runs WITHOUT the person (a scheduled X / Threads post): may the job made for (user, workspace) at
--     lifecycle_version V still run now? 'active' only when ALL of:
--       1. the workspace is the user's PERSONAL one ('u_' || substr(md5(user), 1, 24)) -- the binding is derived, never stored;
--       2. S2-3 answers 'own' for the user: kind social_mobile_user_v1, exactly ONE membership (the user as owner), no other owned brand;
--       3. F5 P5's workspace service state is 'active' (account active, not deleting / locked, x_autopost active, no service deletion);
--       4. the service generation is still V (common_accounts.lifecycle_version: every account / entitlement change bumps it, so an end, a
--          restart, a lock or a deletion makes every earlier job stale) and its two triggers are exactly P1's (generation_covered);
--     otherwise the first failing reason. One snapshot (STABLE), every row visible (row_security = off), no lock, no write.
--     It does NOT use the brand owner epoch (PR #285 / #303 / #457): in the personal MVP the owner is fixed by the derived id and the exact
--     single membership, checked on every call. What that cannot see -- an owner change that is UNDONE between the job's creation and its run
--     (A -> B -> A, only possible today through service_role or the owner writing public.brand_memberships) -- is the MVP's stated residual
--     (docs/common-account/g5-46-postona-personal-mvp-auth.md section 3).
--     Not covered here (their owners' fences): a session ending (P-4, user decision), the SNS connection generation (G4), duplicate sends (G3).
-- Rollback: RM10_personal_worker_verdict_rollback.sql (refuses while anything calls it).

set local lock_timeout = '5s';

do $$
declare
  v_owner oid := (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user);
  v_fn regprocedure;
begin
  if (select r.rolsuper from pg_catalog.pg_roles r where r.oid = v_owner) is distinct from false then
    raise exception 'MV_PRECONDITION_OWNER_IS_SUPERUSER';
  end if;
  if pg_catalog.to_regprocedure('private.postona_personal_worker_verdict(uuid,text,text,bigint)') is not null then
    raise exception 'MV_PRECONDITION_NAME_TAKEN';
  end if;
  -- what it reads: S2-3, P5's state, the generation coverage -- each the lifecycle owner's, definer, empty search_path, executable by its owner only
  foreach v_fn in array array['private.postona_personal_workspace_eligibility(uuid)', 'public.common_account_brand_service_state(text,text)',
                              'private.account_lifecycle_generation_covered()']::regprocedure[] loop
    if v_fn is null or not exists (select 1 from pg_catalog.pg_proc p where p.oid = v_fn and p.proowner = v_owner and p.prosecdef
                                     and p.proconfig @> array['search_path=""']) then
      raise exception 'MV_PRECONDITION_DEPENDENCY %', v_fn;
    end if;
  end loop;
  if exists (select 1 from pg_catalog.pg_proc p, pg_catalog.aclexplode(p.proacl) x
              where p.oid in ('private.postona_personal_workspace_eligibility(uuid)'::regprocedure, 'private.account_lifecycle_generation_covered()'::regprocedure)
                and x.grantee <> p.proowner)
     or exists (select 1 from pg_catalog.pg_proc p
                 where p.oid in ('private.postona_personal_workspace_eligibility(uuid)'::regprocedure, 'private.account_lifecycle_generation_covered()'::regprocedure)
                   and p.proacl is null) then
    raise exception 'MV_PRECONDITION_DEPENDENCY_ACL';
  end if;
  if pg_catalog.to_regclass('public.common_accounts') is null
     or not exists (select 1 from pg_catalog.pg_attribute a where a.attrelid = 'public.common_accounts'::pg_catalog.regclass and not a.attisdropped
                     and a.attname = 'lifecycle_version' and a.atttypid = 'bigint'::pg_catalog.regtype) then
    raise exception 'MV_PRECONDITION_GENERATION_COLUMN';
  end if;
  if not private.account_lifecycle_generation_covered() then
    raise exception 'MV_PRECONDITION_LIFECYCLE_TRIGGERS';
  end if;
end $$;

create function private.postona_personal_worker_verdict(p_user_id uuid, p_brand_id text, p_service_key text, p_expected_lifecycle_version bigint)
returns text language plpgsql stable security definer set search_path = '' set row_security = off as $$
declare
  v_eligibility text;
  v_state text;
  v_lifecycle bigint;
  v_covered boolean;
begin
  if p_user_id is null or p_brand_id is null then
    return 'PERSONAL_WORKER_INPUT_REQUIRED';
  end if;
  if p_service_key is distinct from 'x_autopost' then
    return 'ACCOUNT_LIFECYCLE_SERVICE_INVALID';
  end if;
  if p_expected_lifecycle_version is null or p_expected_lifecycle_version < 1 then
    return 'EXPECTED_LIFECYCLE_VERSION_REQUIRED';
  end if;
  -- 1. the job's workspace must be the user's personal one (derived, as S2-3, the begin RPC and the deletion saga name it)
  if p_brand_id is distinct from 'u_' || pg_catalog.substr(pg_catalog.md5(p_user_id::text), 1, 24) then
    return 'NOT_PERSONAL_WORKSPACE';
  end if;
  -- 2-4. every fact in this one STABLE snapshot
  select private.postona_personal_workspace_eligibility(p_user_id),
         public.common_account_brand_service_state(p_brand_id, p_service_key),
         (select a.lifecycle_version from public.common_accounts a where a.user_id = p_user_id),
         private.account_lifecycle_generation_covered()
    into v_eligibility, v_state, v_lifecycle, v_covered;
  if v_eligibility is distinct from 'own' then
    return case v_eligibility when 'absent' then 'WORKSPACE_ABSENT' when 'WORKSPACE_OWNER_UNKNOWN' then 'WORKSPACE_OWNER_UNKNOWN'
                              else 'OWN_WORKSPACE_CONFLICT' end;
  end if;
  if v_state is distinct from 'active' then
    return case when v_state in ('WORKSPACE_OWNER_UNKNOWN', 'ACCOUNT_LIFECYCLE_ACCOUNT_NOT_FOUND', 'ACCOUNT_DELETION_IN_PROGRESS', 'ACCOUNT_LOCKED',
                                 'SERVICE_NOT_REGISTERED', 'SERVICE_DELETION_IN_PROGRESS', 'SERVICE_NOT_ACTIVE', 'ACCOUNT_LIFECYCLE_SERVICE_INVALID')
                then v_state else 'SERVICE_STATE_UNKNOWN' end;
  end if;
  if v_covered is not true then
    return 'SERVICE_GENERATION_UNAVAILABLE';
  end if;
  if v_lifecycle is distinct from p_expected_lifecycle_version then
    return 'SERVICE_GENERATION_CHANGED';
  end if;
  return 'active';
end $$;

revoke all on function private.postona_personal_worker_verdict(uuid, text, text, bigint) from public, anon, authenticated, service_role;

do $$
declare v_fn regprocedure := 'private.postona_personal_worker_verdict(uuid,text,text,bigint)'::regprocedure;
begin
  if (select pg_catalog.array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_fn) is distinct from pg_catalog.format('%s=X/%s', current_user, current_user)
     or exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
                 where a.rolname in ('anon', 'authenticated', 'service_role', 'authenticator') and pg_catalog.has_function_privilege(r.oid, v_fn, 'EXECUTE')) then
    raise exception 'MV_POSTCONDITION_ACL';
  end if;
end $$;


-- ==== G5-46 MVP POSTCONDITION: every gate is the lifecycle owner's, owner-only, unreachable by any API role ====
do $$
declare v_sig text;
begin
  foreach v_sig in array array['private.postona_personal_session()', 'private.postona_personal_workspace_eligibility(uuid)', 'private.account_lifecycle_assert_active_service_write(uuid,text)', 'private.account_lifecycle_generation_covered()', 'private.postona_personal_worker_verdict(uuid,text,text,bigint)'] loop
    if pg_catalog.to_regprocedure(v_sig) is null
       or (select pg_catalog.array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = pg_catalog.to_regprocedure(v_sig))
          is distinct from pg_catalog.format('%s=X/%s', current_user, current_user)
       or (select p.proowner from pg_catalog.pg_proc p where p.oid = pg_catalog.to_regprocedure(v_sig))
          is distinct from (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user)
       or exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
                   where a.rolname in ('anon', 'authenticated', 'service_role', 'authenticator')
                     and pg_catalog.has_function_privilege(r.oid, pg_catalog.to_regprocedure(v_sig), 'EXECUTE')) then
      raise exception 'MVP_POSTCONDITION_ACL %', v_sig;
    end if;
  end loop;
end $$;

commit;
